<?php
require __DIR__.'/../src/bootstrap.php';
$user=requireLogin();$id=intField($_GET,'id')??0;$db=Database::connection();
$loadOrder=function()use($db,$id){$q=$db->prepare('SELECT o.*,p.code point_code,p.name point_name,w.code warehouse_code,w.name warehouse_name FROM sales_orders o JOIN sales_points p ON p.id=o.sales_point_id JOIN warehouses w ON w.id=o.warehouse_id WHERE o.id=:id');$q->execute(['id'=>$id]);return $q->fetch();};
$order=$loadOrder();if(!$order)forbid('ORDER_NOT_FOUND');if(!canAccessWarehouse($user,(int)$order['warehouse_id'])&&!canAccessSalesPoint($user,(int)$order['sales_point_id']))forbid('ORDER_SCOPE_FORBIDDEN');$error='';$cancelReasonInput='';
if($_SERVER['REQUEST_METHOD']==='POST'){requirePost();try{$action=field($_POST,'action');if($action==='approve')SalesOrderService::approve($user,$id);elseif($action==='cancel'){$cancelReasonInput=field($_POST,'cancel_reason');SalesOrderService::cancel($user,$id,$cancelReasonInput);}elseif($action==='dispatch'){ $lines=[];$q2=$db->prepare('SELECT * FROM sales_order_lines WHERE order_id=:id');$q2->execute(['id'=>$id]);foreach($q2 as $l){$remaining=(int)$l['requested_qty']-(int)$l['allocated_qty'];if($remaining>0)$lines[]=['batch_id'=>$l['batch_id'],'qty'=>$remaining];}SalesOrderService::dispatch($user,$id,$lines,field($_POST,'request_key'));}elseif($action==='receive'){ $received=[];$batchIds=listField($_POST,'batch_id');$qtys=listField($_POST,'received_qty');foreach($batchIds as $i=>$b)$received[(int)$b]=$qtys[$i]??null;$deliveryId=intField($_POST,'delivery_id');$owns=$db->prepare('SELECT 1 FROM sales_deliveries WHERE id=:delivery AND order_id=:order');$owns->execute(['delivery'=>$deliveryId??0,'order'=>$id]);if(!$owns->fetchColumn())throw new DomainException('DELIVERY_NOT_FOUND');SalesOrderService::receive($user,$deliveryId,$received);}flash($action==='cancel'?'Đã hủy đơn phân phối.':'Đã cập nhật đơn phân phối.');redirect('/sales-order.php?id='.$id);}catch(DomainException $e){$error=ERROR_LABELS[$e->getMessage()]??'Không cập nhật được đơn phân phối. Trạng thái đơn có thể đã thay đổi; tải lại trang rồi thử lại.';}catch(Throwable $e){error_log('Sales order update failed: '.$e->getMessage());$error='Không cập nhật được đơn phân phối. Vui lòng thử lại.';}$order=$loadOrder()?:$order;}
// Tổng đã nhận / thiếu theo từng dòng đơn, cộng dồn qua mọi lần giao.
$lq=$db->prepare('SELECT l.*,i.name item_name,i.sku,b.code batch_code,COALESCE(SUM(dl.shipped_qty),0) shipped_total,COALESCE(SUM(dl.received_qty),0) received_total,COALESCE(SUM(dl.shortage_qty),0) shortage_total FROM sales_order_lines l JOIN items i ON i.id=l.item_id JOIN batches b ON b.id=l.batch_id LEFT JOIN sales_delivery_lines dl ON dl.order_line_id=l.id WHERE l.order_id=:id GROUP BY l.id,i.name,i.sku,b.code ORDER BY l.id');$lq->execute(['id'=>$id]);$lines=$lq->fetchAll();
$dq=$db->prepare("SELECT d.*,v.id voucher_id,v.code voucher_code FROM sales_deliveries d LEFT JOIN vouchers v ON v.type='sale' AND v.code=d.code WHERE d.order_id=:id ORDER BY d.id");$dq->execute(['id'=>$id]);$deliveries=$dq->fetchAll();$dlq=$db->prepare('SELECT dl.*,i.name item_name,b.code batch_code FROM sales_delivery_lines dl JOIN sales_order_lines ol ON ol.id=dl.order_line_id JOIN items i ON i.id=ol.item_id JOIN batches b ON b.id=dl.batch_id WHERE dl.delivery_id=:id ORDER BY dl.id');foreach($deliveries as &$delivery){$dlq->execute(['id'=>$delivery['id']]);$delivery['lines']=$dlq->fetchAll();}unset($delivery);
$itemsById=Store::indexed('items');
$canSeeVoucher=canAccessWarehouse($user,(int)$order['warehouse_id']);
$canCancel=!$deliveries&&SalesOrderService::canCancel($user,$order);
$totalShortage=array_sum(array_map(fn($l)=>(int)$l['shortage_total'],$lines));
$uid=fn($v)=>$v===null?null:(int)$v;
$title=$order['code'];$active='sales-orders';require __DIR__.'/../templates/header.php';
?>
<nav class="breadcrumb"><a href="/sales-orders.php">Đơn phân phối</a> / <?=e($order['code'])?></nav><header class="page-head"><div><h1><?=e($order['code'])?> <?=salesStatusBadge($order['status'])?></h1><p><?=e($order['warehouse_name'].' → '.$order['point_name'])?></p></div></header>
<?php if($error):?><div class="error-summary" role="alert"><?=e($error)?></div><?php endif;?>
<section class="card"><dl class="meta">
<div><dt>Kho xuất</dt><dd><?=e($order['warehouse_code'].' · '.$order['warehouse_name'])?></dd></div>
<div><dt>Điểm bán</dt><dd><?=e($order['point_code'].' · '.$order['point_name'])?></dd></div>
<div><dt>Người tạo</dt><dd><?=e(userName($uid($order['created_by'])))?> · <?=e(dateOnly($order['created_at']))?></dd></div>
<div><dt>Người duyệt</dt><dd><?=$order['approved_by']!==null?e(userName($uid($order['approved_by']))).' · '.e(dateOnly($order['approved_at'])):'Chưa duyệt'?></dd></div>
<?php if($order['status']==='CANCELLED'):?><div><dt>Người hủy</dt><dd><?=e(userName($uid($order['cancelled_by']??null)))?><?=!empty($order['cancelled_at'])?' · '.e(dateOnly($order['cancelled_at'])):''?></dd></div><div><dt>Lý do hủy</dt><dd><?=e(($order['cancel_reason']??'')?:'Không có lý do được lưu.')?></dd></div><?php endif;?>
<div><dt>Ghi chú</dt><dd><?=e($order['note']?:'—')?></dd></div>
</dl></section>
<section class="card"><h2>Dòng hàng</h2><div class="table-wrap"><table class="table"><thead><tr><th>Mã</th><th>Mặt hàng</th><th>Lô</th><th>ĐVT</th><th class="num">Đặt</th><th class="num">Đã xuất</th><th class="num">Đã nhận</th><th class="num">Thiếu</th><th class="num">Còn phải xuất</th></tr></thead><tbody><?php foreach($lines as $l):?><tr><td><?=e($l['sku'])?></td><td><?=e($l['item_name'])?></td><td><?=e($l['batch_code'])?></td><td><?=e($itemsById[(int)$l['item_id']]['unit_name']??'')?></td><td class="num"><?=qty((int)$l['requested_qty'])?></td><td class="num"><?=qty((int)$l['allocated_qty'])?></td><td class="num"><?=qty((int)$l['received_total'])?></td><td class="num"><?=(int)$l['shortage_total']>0?'<span class="qty-neg">'.qty((int)$l['shortage_total']).'</span>':'0'?></td><td class="num"><?=qty(max(0,(int)$l['requested_qty']-(int)$l['allocated_qty']))?></td></tr><?php endforeach;?></tbody></table></div>
<?php if($totalShortage>0):?><p class="notice">Điểm bán đã ghi nhận nhận thiếu tổng <?=qty($totalShortage)?> đơn vị. Phần thiếu được lưu trong biên bản từng lần giao bên dưới.</p><?php endif;?>
<div class="actions"><?php if(in_array($order['status'],['PENDING'],true)&&in_array($user['role'],['approver','admin','central_manager','regional_manager'],true)):?><form method="post"><?=csrfInput()?><input type="hidden" name="action" value="approve"><button class="button">Duyệt đơn</button></form><?php endif;?><?php if(in_array($order['status'],['APPROVED','DELIVERING','PARTIALLY_RECEIVED'],true)&&in_array($user['role'],['staff','regional_manager','admin'],true)&&array_sum(array_map(fn($l)=>(int)$l['requested_qty']-(int)$l['allocated_qty'],$lines))>0):?><form method="post"><?=csrfInput()?><input type="hidden" name="action" value="dispatch"><input type="hidden" name="request_key" value="<?=e(bin2hex(random_bytes(32)))?>"><button class="button">Xuất phần còn lại</button></form><?php endif;?>
<?php if($canCancel):?><details class="reject-disclosure" <?=$cancelReasonInput!==''||$error!==''&&field($_POST,'action')==='cancel'?'open':''?>><summary class="button button--ghost">Hủy đơn</summary><form method="post" class="reject-form"><?=csrfInput()?><input type="hidden" name="action" value="cancel"><label class="label" for="cancel_reason">Lý do hủy <span>(bắt buộc)</span></label><textarea id="cancel_reason" name="cancel_reason" rows="3" maxlength="255" required><?=e($cancelReasonInput)?></textarea><button class="button button--danger">Xác nhận hủy đơn</button></form></details><?php endif;?></div></section>
<?php foreach($deliveries as $d):?><section class="card"><h2>Lần giao <?=e($d['code'])?> <?=salesStatusBadge($d['status'],true)?></h2><dl class="meta"><div><dt>Người giao</dt><dd><?=e(userName($uid($d['delivered_by'])))?> · <?=e(dateOnly($d['delivered_at']))?></dd></div><div><dt>Người nhận</dt><dd><?=$d['received_by']!==null?e(userName($uid($d['received_by']))).' · '.e(dateOnly($d['received_at'])):'Chưa xác nhận'?></dd></div><div><dt>Chứng từ xuất kho</dt><dd><?php if($d['voucher_id']!==null&&$canSeeVoucher):?><a class="text-link" href="/voucher.php?id=<?=(int)$d['voucher_id']?>"><?=e($d['voucher_code'])?></a><?php else:?><?=e($d['voucher_code']??'—')?><?php endif;?></dd></div><?php if($d['note']!==''):?><div><dt>Ghi chú</dt><dd><?=e($d['note'])?></dd></div><?php endif;?></dl>
<?php if(in_array($d['status'],['DELIVERING','PARTIALLY_RECEIVED'],true)&&SalesOrderService::canConfirmReceipt($user,(int)$order['sales_point_id'])):?><form method="post"><?=csrfInput()?><input type="hidden" name="action" value="receive"><input type="hidden" name="delivery_id" value="<?=$d['id']?>"><?php foreach($d['lines'] as $dl):?><input type="hidden" name="batch_id[]" value="<?=$dl['batch_id']?>"><label class="form-field"><?=e($dl['item_name'].' · '.$dl['batch_code'].' (giao '.qty((int)$dl['shipped_qty']).')')?><input type="number" min="<?=e((string)(int)($dl['received_qty']??0))?>" max="<?=e((string)(int)$dl['shipped_qty'])?>" name="received_qty[]" value="<?=e((string)(int)($dl['received_qty']??0))?>" required></label><?php endforeach;?><button class="button">Xác nhận số nhận</button></form>
<?php else:?><div class="table-wrap"><table class="table table--compact"><thead><tr><th>Mặt hàng</th><th>Lô</th><th class="num">Đã giao</th><th class="num">Thực nhận</th><th class="num">Thiếu</th></tr></thead><tbody><?php foreach($d['lines'] as $dl):?><tr><td><?=e($dl['item_name'])?></td><td><?=e($dl['batch_code'])?></td><td class="num"><?=qty((int)$dl['shipped_qty'])?></td><td class="num"><?=$dl['received_qty']===null?'—':qty((int)$dl['received_qty'])?></td><td class="num"><?=qty((int)$dl['shortage_qty'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php endforeach;?>
<?php require __DIR__.'/../templates/footer.php';
